 if(!ST.sp){try{const v=JSON.parse(localStorage.getItem('fundlens.stressPeriods')||'null');if(v&&Array.isArray(v.periods))ST.sp=v;}catch(e){}if(!ST.sp)ST.sp=DEF();}
 const saveSP=()=>{try{localStorage.setItem('fundlens.stressPeriods',JSON.stringify(ST.sp));}catch(e){}};
 const isDefault=()=>JSON.stringify(ST.sp)===JSON.stringify(DEF());
 let LC={key:null};const live=()=>{const key=JSON.stringify(ST.sp);if(LC.key!==key){const SE=window.StressEngine,fl=SE.flags(D,ST.sp),corr=SE.correlations(D,fl);LC={key,fl,corr,lift:SE.lift(D,fl),replay:SE.replay(D,ST.sp.periods,AUM),tail:SE.tailHist(D,corr['daily|raw|stress'])};}return LC;};
 const banner=()=>{const L=live(),on=ST.sp.periods.filter(p=>p.on);return `<div class="sp-banner"><div><b>Stress definition${isDefault()?' (notebook default)':' (custom: results recomputed live)'}:</b> ${ST.sp.dd?`price ≥${pct(ST.sp.dd,0)} below its one-year high`:'no price trigger'}${on.length?` or inside ${on.length} period${on.length>1?'s':''} (${on.map(p=>esc(p.name)).join(', ')})`:''} · <b>${L.fl.days.toLocaleString()}</b> stress days (${pct(L.fl.days/D.daily.dates.length)} of history)</div>${ST.tab!=='stress'?'<button type="button" data-goto="stress">Edit stress periods</button>':''}</div>`;};
 const allTests=()=>{const L=live();return D.tests.filter(t=>t.family!=='Named episode'&&!/historical stress correlation/.test(t.scenario)).concat(L.replay).concat(L.tail.map(x=>({family:'Segment tails',scenario:`${x.h}-day 99th pct, historical stress correlation`,outflow_gbp:x.gbp,outflow_share:x.gbp/AUM,payables_included_gbp:0})));};
 const tight=s=>{const c=coh[s];if(s==='Rare traders'||!c||c.silhouette===undefined||c.silhouette===null)return ['Not clustered','#8795a8','Set aside for too little history; the label says little about behaviour.'];const ratio=(c.flow_r_within||0)/Math.max(.01,D.random_pair_r);
  return c.well_fitted_share>=.25&&ratio>=2.5?['Tight group','#1baf7a',`${pct(c.well_fitted_share,0)} clearly belong; members move money together ${ratio.toFixed(1)}× as much as random clients.`]:(ratio>=1.5||c.well_fitted_share>=.15)?['Loose group','#eda100',`${pct(c.well_fitted_share,0)} clearly belong; members move together ${ratio.toFixed(1)}× as much as random clients.`]:['Label only','#e34948',`Only ${pct(c.well_fitted_share,0)} clearly belong and members move together about as much as random clients (${ratio.toFixed(1)}×). Treat clients individually.`];};
 const conc=D.concentration.at(-1),worst5=Math.max(...D.tests.filter(t=>t.family==='Historical replay'&&/5-day/.test(t.scenario)).map(t=>t.outflow_gbp)),rare=prof['Rare traders'],eligible=D.typical.clients;
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">Segments & stress · Notebook 11</div><h1>Who could leave, together, and could we pay?</h1><p class="muted">How clients were grouped by behaviour, how each group redeems in stress periods, and whether the fund could meet large withdrawals. Position at ${esc(base.date)}: AUM ${gbp(AUM)}.</p></div><div class="controls"><a class="button" href="11_segments_correlation_stress.html">Open full notebook ↗</a><a class="button" download href="11_client_segments.csv">Client → segment file ↓</a></div></div>
 <div class="tabs" role="tablist">${TABS.map(([k,v])=>`<button role="tab" data-tab="${k}" aria-selected="${ST.tab===k}">${v}</button>`).join('')}</div><div id="sg-body"></div>
 <div class="note">Synthetic data. Segments describe past behaviour, not future intentions. Stress scenarios are illustrative exposures, not probabilities. The database has no portfolio holdings, so liquid assets cannot be measured: buffers are illustrative.</div>`;
 const $=id=>app.querySelector('#'+id);
 const go=t=>{ST.tab=t;app.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x.dataset.tab===t)));draw();if(window.scrollTo)try{window.scrollTo({top:0,behavior:'smooth'});}catch(e){}};
 app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));
 const bind=(id,k,fn=v=>v)=>{const e=$(id);if(e){e.value=String(ST[k]);e.onchange=()=>{ST[k]=fn(e.value);draw();};}};
