  const N=D.seg_net,shown=order.filter(s=>ST.netSegs.has(s));$('sg-net').innerHTML=C().line({labels:N.months,series:shown.map(s=>({label:s,color:col(s),values:N.series[s]})),yTitle:'Net flow per month (GBP)',xTitle:'Month',title:'Monthly net flow by segment',noDots:true,empty:'Select at least one segment.'});
